// @ts-ignore Generated by the OpenNext build and absent before the first build.
import handler from './.open-next/worker.js'
// @ts-ignore Generated after OpenNext emits the static assets.
import publicVideoSizes from './.open-next/public-video-sizes.json'

const dailyCronRoutes: Record<number, string> = {
  3: '/api/cron/launch-campaign',
  4: '/api/cron/account-cleanup',
  5: '/api/cron/billing',
  6: '/api/cron/check-tokens',
  7: '/api/cron/sync-google-reviews',
}

type WorkerEnv = {
  ASSETS?: { fetch(request: Request): Promise<Response> }
  APP_URL?: string
  CRON_SECRET?: string
  ENABLE_CRON_TRIGGERS?: string
  BOOKEASY_CLOUDFLARE_PREVIEW?: string
}

type CronEvent = { cron: string; scheduledTime: number }
type WorkerContext = { waitUntil(promise: Promise<unknown>): void }

declare class FixedLengthStream {
  constructor(length: number)
  readable: ReadableStream<Uint8Array>
  writable: WritableStream<Uint8Array>
}

function sliceVideo(body: ReadableStream<Uint8Array>, start: number, end: number) {
  const reader = body.getReader()
  let offset = 0
  return new ReadableStream<Uint8Array>({
    async pull(controller) {
      while (true) {
        const { done, value } = await reader.read()
        if (done) throw new Error('Video asset ended before the requested range.')
        const from = Math.max(0, start - offset)
        const to = Math.min(value.byteLength, end + 1 - offset)
        offset += value.byteLength
        if (to <= from) continue
        controller.enqueue(value.subarray(from, to))
        if (offset > end) {
          controller.close()
          await reader.cancel().catch(() => {})
        }
        return
      }
    },
    cancel(reason) { return reader.cancel(reason) },
  })
}

async function fetchPublicVideo(request: Request, url: URL, env: WorkerEnv, ctx: WorkerContext) {
  if (!env.ASSETS || !/^(GET|HEAD)$/.test(request.method) || !/^\/(tutorials|videos)\/.+\.mp4$/i.test(url.pathname)) return

  const assetRequest = new Request(request)
  assetRequest.headers.delete('range')
  assetRequest.headers.delete('if-range')
  assetRequest.headers.set('accept-encoding', 'identity')
  const asset = await env.ASSETS.fetch(assetRequest)
  const headers = new Headers(asset.headers)
  if (env.BOOKEASY_CLOUDFLARE_PREVIEW === 'true') headers.set('X-Robots-Tag', 'noindex, nofollow')
  const fullResponse = () => new Response(asset.body, { status: asset.status, statusText: asset.statusText, headers })

  const contentLength = headers.get('content-length')
  const size = contentLength && /^\d+$/.test(contentLength)
    ? Number(contentLength)
    : (publicVideoSizes as Record<string, number>)[url.pathname]
  const encoding = headers.get('content-encoding')
  if (asset.status !== 200 || !Number.isSafeInteger(size) || size <= 0 || (encoding && encoding !== 'identity')) {
    return fullResponse()
  }
  headers.set('Accept-Ranges', 'bytes')
  const range = request.headers.get('range')
  const ifRange = request.headers.get('if-range')
  // Only the asset's strong ETag is sufficient to combine with previously downloaded bytes.
  const matchesValidator = ifRange === null || (ifRange.startsWith('"') && ifRange === headers.get('etag'))
  const bounds = range && /^bytes=(\d*)-(\d*)$/i.exec(range)
  if (request.method !== 'GET' || !asset.body || !matchesValidator || !bounds || (!bounds[1] && !bounds[2])) {
    return fullResponse()
  }

  const start = bounds[1] ? Number(bounds[1]) : Math.max(0, size - Number(bounds[2]))
  const end = bounds[1] && bounds[2] ? Math.min(Number(bounds[2]), size - 1) : size - 1
  if (start > end) {
    await asset.body.cancel()
    headers.set('Content-Range', `bytes */${size}`)
    headers.set('Content-Length', '0')
    return new Response(null, { status: 416, headers })
  }

  const length = end - start + 1
  const partial = new FixedLengthStream(length)
  headers.set('Content-Range', `bytes ${start}-${end}/${size}`)
  headers.set('Content-Length', String(length))
  ctx.waitUntil(sliceVideo(asset.body, start, end).pipeTo(partial.writable).catch(() => {
    // The response stream propagates errors to the client, which can retry or cancel.
  }))
  return new Response(partial.readable, { status: 206, headers })
}

export default {
  async fetch(request: Request, env: WorkerEnv, ctx: WorkerContext) {
    const video = await fetchPublicVideo(request, new URL(request.url), env, ctx)
    if (video) return video
    const response = await handler.fetch(request, env, ctx)
    if (env.BOOKEASY_CLOUDFLARE_PREVIEW !== 'true') return response
    const headers = new Headers(response.headers)
    headers.set('X-Robots-Tag', 'noindex, nofollow')
    return new Response(response.body, { status: response.status, statusText: response.statusText, headers })
  },
  async scheduled(event: CronEvent, env: WorkerEnv, ctx: WorkerContext) {
    if (env.BOOKEASY_CLOUDFLARE_PREVIEW === 'true' || env.ENABLE_CRON_TRIGGERS !== 'true') return
    const route = event.cron === '*/5 * * * *'
      ? '/api/cron/billing-payments'
      : event.cron === '0 3-7 * * *'
        ? dailyCronRoutes[new Date(event.scheduledTime).getUTCHours()]
        : undefined
    if (!route || !env.APP_URL || !env.CRON_SECRET) return

    // Dispatch internally: a same-zone fetch on a Worker route can reach the
    // legacy DNS origin instead of this Worker.
    ctx.waitUntil((async () => {
      const response = await handler.fetch(new Request(`${env.APP_URL}${route}`, {
        headers: { Authorization: `Bearer ${env.CRON_SECRET}` },
      }), env, ctx)
      await response.arrayBuffer()
      if (!response.ok) throw new Error(`Cron ${route} failed: HTTP ${response.status}`)
    })())
  },
}
